public int numDecodings(String s) {
    int n = s.length();
    int oneAhead = 1; // dp[n]
    int twoAhead = 0; // dp[n+1]
    for (int i = n - 1; i >= 0; i--) {
        int cur = 0;
        if (s.charAt(i) != '0') {
            cur += oneAhead;
            if (i + 1 < n && Integer.parseInt(s.substring(i, i + 2)) <= 26) {
                cur += twoAhead;
            }
        }
        twoAhead = oneAhead;
        oneAhead = cur;
    }
    return oneAhead;
}

