def numDecodings(self, s: str) -> int:
    n = len(s)
    one_ahead, two_ahead = 1, 0  # dp[n], dp[n+1]
    for i in range(n - 1, -1, -1):
        cur = 0
        if s[i] != '0':
            cur += one_ahead
            if i + 1 < n and int(s[i:i + 2]) <= 26:
                cur += two_ahead
        two_ahead, one_ahead = one_ahead, cur
    return one_ahead
